"use client"

import { createContext, useContext, useState, useEffect, useCallback, useRef } from 'react'
import { usePathname, useSearchParams } from 'next/navigation'
import { motion, AnimatePresence } from 'framer-motion'
import { Loader2 } from 'lucide-react'

interface NavigationLoadingContextType {
  isNavigating: boolean
  startNavigation: () => void
  stopNavigation: () => void
}

const NavigationLoadingContext = createContext<NavigationLoadingContextType>({
  isNavigating: false,
  startNavigation: () => {},
  stopNavigation: () => {}
})

export function useNavigationLoading() {
  return useContext(NavigationLoadingContext)
}

export function NavigationLoadingProvider({ children }: { children: React.ReactNode }) {
  const [isNavigating, setIsNavigating] = useState(false)
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const navigationTimeoutRef = useRef<NodeJS.Timeout>()
  const loadingStartTimeRef = useRef<number>(0)

  // Clear loading state when pathname actually changes (navigation complete)
  useEffect(() => {
    // Clear any pending timeouts
    if (navigationTimeoutRef.current) {
      clearTimeout(navigationTimeoutRef.current)
    }

    // Stop navigation loading when route changes
    if (isNavigating) {
      // Add small delay to ensure smooth transition
      setTimeout(() => {
        setIsNavigating(false)
      }, 100)
    }
  }, [pathname, searchParams])

  // Failsafe: Always clear loading after max 5 seconds
  useEffect(() => {
    if (isNavigating) {
      const failsafeTimeout = setTimeout(() => {
        console.warn('Navigation loading timeout - clearing loading state')
        setIsNavigating(false)
      }, 5000)

      return () => clearTimeout(failsafeTimeout)
    }
  }, [isNavigating])

