import { requireRole } from "@/lib/auth/utils"
import { createServerSupabaseClient } from "@/lib/supabase/server"
import Link from "next/link"
import { redirect } from "next/navigation"
import {
  LayoutDashboard,
  User,
  Shield,
  Calendar,
  ClipboardList,
  FileText,
  MessageSquare,
  Settings,
  LogOut,
  AlertCircle,
  Briefcase
} from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { SidebarSignOut } from "@/components/sidebar-signout"

const navItems = [
  {
    label: "Dashboard",
    href: "/coach/dashboard",
    icon: LayoutDashboard
  },
  {
    label: "Profile",
    href: "/coach/profile",
    icon: User
  },
  {
    label: "Find Work",
    href: "/coach/listings",
    icon: Briefcase
  },
  {
    label: "My Applications",
    href: "/coach/applications",
    icon: FileText
  },
  {
    label: "Verification",
    href: "/coach/verify",
    icon: Shield
  },
  {
    label: "Availability",
    href: "/coach/availability",
    icon: Calendar
  },
  {
    label: "Settings",
    href: "/coach/settings",
    icon: Settings
  }
]

export default async function CoachLayout({
  children,
}: {
  children: React.ReactNode
}) {
  const user = await requireRole('coach')
  const supabase = await createServerSupabaseClient()

  // Get coach profile to check verification status
  const { data: profile } = await supabase
    .from('coach_profiles')
    .select('*')
    .eq('user_id', user.id)
    .single()

  const isVerified = !!(profile?.wwcc_number && profile?.insurance_url && profile?.first_aid_url)

  return (
    <div className="flex min-h-[calc(100vh-4rem)]">
      {/* Sidebar */}
      <aside className="w-64 border-r bg-muted/20">
        <div className="p-6">
          <h2 className="text-lg font-semibold mb-2">Coach Portal</h2>
          <p className="text-sm text-muted-foreground">{user.email}</p>
          <div className="mt-3">
            {isVerified ? (
              <Badge className="bg-green-500/10 text-green-700 border-green-200">
                <Shield className="w-3 h-3 mr-1" />
                Verified
              </Badge>
            ) : (
              <Badge variant="secondary">
                <AlertCircle className="w-3 h-3 mr-1" />
                Unverified
              </Badge>
            )}
          </div>
        </div>

        <nav className="px-4 space-y-1">
          {navItems.map((item) => (
