@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  /* Glassmorphism variables */
  --glass-blur: 16px;
  --glass-saturation: 150%;
  --glass-opacity: 0.7;
  --glass-border-opacity: 0.2;

  /* Typography scale */
  --text-h1: clamp(3rem, 5vw, 4rem);
  --text-h2: clamp(2rem, 4vw, 2.5rem);
  --text-h3: clamp(1.5rem, 3vw, 1.875rem);
  --text-body: 1rem;
  --text-body-lg: 1.125rem;
  --text-sm: 0.875rem;
}

:root {
  --radius: 0.625rem;
  /* Light mode - Clean whites with subtle grays */
  --background: oklch(0.99 0 0);
  --foreground: oklch(0.20 0.02 250);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.20 0.02 250);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.20 0.02 250);
  /* Primary - Vibrant cyan from logo */
  --primary: oklch(0.75 0.15 195);
  --primary-foreground: oklch(1 0 0);
  /* Secondary - Teal/mint from logo */
  --secondary: oklch(0.70 0.12 170);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.96 0.01 250);
  --muted-foreground: oklch(0.45 0.02 250);
  /* Accent - Bright cyan */
  --accent: oklch(0.80 0.15 195);
  --accent-foreground: oklch(0.15 0.02 250);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.92 0.01 250);
  --input: oklch(0.96 0.01 250);
  --ring: oklch(0.75 0.15 195);
  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.97 0 0);
  --sidebar-accent-foreground: oklch(0.205 0 0);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.708 0 0);
}

.dark {
  /* Dark mode - Navy from logo background */
  --background: oklch(0.22 0.04 250);
  --foreground: oklch(0.95 0 0);
  --card: oklch(0.25 0.04 250);
  --card-foreground: oklch(0.90 0 0); /* Ensure good contrast */
  --popover: oklch(0.25 0.04 250);
  --popover-foreground: oklch(0.95 0 0);
  /* Primary - Vibrant cyan (brighter in dark mode) */
  --primary: oklch(0.80 0.18 195);
  --primary-foreground: oklch(0.15 0.02 250);
  /* Secondary - Teal/mint (brighter in dark mode) */
  --secondary: oklch(0.75 0.15 170);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.556 0 0);
  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.556 0 0);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

@layer utilities {
  /* Glassmorphism utilities */
  .glass {
    background: rgba(255, 255, 255, var(--glass-opacity));
    backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturation));
    -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturation));
    border: 1px solid rgba(255, 255, 255, var(--glass-border-opacity));
    color: oklch(0.20 0.02 250); /* Dark text for light background */
  }

  .glass-dark {
    background: rgba(0, 0, 0, var(--glass-opacity));
    backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturation));
    -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturation));
    border: 1px solid rgba(255, 255, 255, var(--glass-border-opacity));
    color: oklch(0.95 0 0); /* Light text for dark background */
  }

  /* Dark mode glass card text fix */
  .dark .glass {
    background: rgba(30, 35, 45, 0.8);
    backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturation));
    -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturation));
    border: 1px solid rgba(255, 255, 255, 0.1);
    color: oklch(0.95 0 0); /* Light text in dark mode */
  }

  .dark .glass-dark {
    background: rgba(10, 12, 18, 0.9);
    color: oklch(0.95 0 0); /* Light text in dark mode */
  }

  /* Ensure all text in glass cards is readable */
  .glass h1, .glass h2, .glass h3, .glass h4, .glass h5, .glass h6,
  .glass p, .glass span, .glass div, .glass label {
    color: inherit;
  }

  .dark .glass h1, .dark .glass h2, .dark .glass h3,
  .dark .glass h4, .dark .glass h5, .dark .glass h6,
  .dark .glass p, .dark .glass span, .dark .glass div,
  .dark .glass label, .dark .glass .text-muted-foreground {
    color: oklch(0.85 0 0);
  }

  .dark .glass .text-muted-foreground {
    color: oklch(0.70 0 0) !important;
  }

  /* Animation utilities */
  @keyframes shimmer {
    100% {
      transform: translateX(100%);
    }
  }

  @keyframes pulse-ring {
    0% {
      transform: scale(0.95);
      opacity: 1;
    }
    50% {
      transform: scale(1.05);
      opacity: 0.7;
    }
    100% {
      transform: scale(0.95);
      opacity: 1;
    }
  }

  @keyframes slide-up-fade {
    0% {
      opacity: 0;
      transform: translateY(10px);
    }
    100% {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes scale-in {
    0% {
      opacity: 0;
      transform: scale(0.95);
    }
    100% {
      opacity: 1;
      transform: scale(1);
    }
  }

  .animation-delay-200 {
    animation-delay: 200ms;
  }

  .animation-delay-400 {
    animation-delay: 400ms;
  }

  .animation-delay-600 {
    animation-delay: 600ms;
  }

  /* Typography utilities */
  .text-h1 {
    font-size: var(--text-h1);
    line-height: 1.1;
    font-weight: 700;
    letter-spacing: -0.02em;
  }

  .text-h2 {
    font-size: var(--text-h2);
    line-height: 1.2;
    font-weight: 600;
    letter-spacing: -0.01em;
  }

  .text-h3 {
    font-size: var(--text-h3);
    line-height: 1.3;
    font-weight: 600;
  }

  .text-body-lg {
    font-size: var(--text-body-lg);
    line-height: 1.6;
  }

  /* Shadow utilities */
  .shadow-soft {
    box-shadow: 0 4px 20px -2px rgba(0, 0, 0, 0.08),
                0 2px 8px -2px rgba(0, 0, 0, 0.04);
  }

  .shadow-soft-lg {
    box-shadow: 0 10px 40px -10px rgba(0, 0, 0, 0.1),
                0 4px 16px -4px rgba(0, 0, 0, 0.05);
  }
}

